	_a.make_read_only()
	print("is_same getter same: ", is_same(get_a(), get_a()), " ; == : ", get_a() == get_a())
	print("is_same copy: ", is_same(get_copy(), get_copy()), " ; == : ", get_copy() == get_copy())
