	for i in 100000:
		var t: Array[int] = [i, i + 1, i + 2]
		var s: String = str(i)
		t.append(s.length())
	print("transient loop MEMORY_STATIC delta=", Performance.get_monitor(Performance.MEMORY_STATIC) - m0, " OBJECT_COUNT delta=", Performance.get_monitor(Performance.OBJECT_COUNT) - oc0)
	var retained: Array = []
	for i in 10000:
		retained.append([i])
	print("retained 10000 small arrays MEMORY_STATIC delta=", Performance.get_monitor(Performance.MEMORY_STATIC) - m0, " OBJECT_COUNT delta=", Performance.get_monitor(Performance.OBJECT_COUNT) - oc0)
